INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63067052', 63067052, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'POLITEKNIK KESEHATAN MALANG', 'Belanja Modal Peralatan Dan Mesin – BLU Pengadaan ABBM Laboratorium Pendidikan Laboratorium Keperawatan Lawang Berupa Phantom anak (Pediatric care simulator), IV Hand, Phantom injeksi anak/bayi, Keranjang pakaian kotor standar, Manikin bayi untuk memasang NGT, Kursi roda berkunci, IV hand anak, Kruk (Crutches dengan ujung berlapis karet), Alat perawatan tali pusat, Stetoskop untuk tindakan mengukur tekanan darah, dan Foot stool / foot board.', 'Barang', 'E-Purchasing', 'Jawa Timur, Malang (Kota)', 144658000, 'January 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '22 Unit', 'Phantom anak (Pediatric care simulator) = 4 Unit IV Hand = 2 Unit Phantom injeksi anak/bayi = 2 Unit Keranjang pakaian kotor standar = 1 Unit Manikin bayi untuk memasang NGT = 1 Unit Kursi roda berkunci = 1 Unit IV hand anak = 1 Unit Kruk (Crutches dengan ujung berlapis karet) = 2 Unit Alat perawatan tali pusat = 1 Unit Stetoskop untuk tindakan mengukur tekanan darah = 3 Unit Foot stool / foot board = 4 Unit', 'Phantom anak (Pediatric care simulator) 4 Unit = "PHANTOM MANEKIN AUTO BODY ANAK TERBUAT DARI BAHAN SILICON" IV Hand 2 Unit = "PHANTOM MANEKIN PEMASANGAN INFUS LENGAN PRODUK TERBUAT DARI BAHAN SILICON DILENGKAPI DENGAN TIANG PENYANGGA INFUS DAN 1 BOTOL AIR INFUS" Phantom injeksi anak/bayi 2 Unit = "PHANTOM MANEKIN BAYI INJEKSI TERBUAT DARI BAHAN SILICON PRODUK ASLI INDONESIA" Keranjang pakaian kotor standar 1 Unit = "Konstruksi : Pipa dan plat besi Ukuran : 110 x 63 x 110 (cm) Roda : 4 inch (2 rem, 2 pengunci) Finishing : Cat duco Terdapat pintu untuk linen bersih dan keranjang untuk linen kotor" Manikin bayi untuk memasang NGT 1 Unit = "PHANTOM MANEKIN NGT SONDE TERBUAT DARI BAHAN SILICON" Kursi roda berkunci 1 Unit = Bahan Stainless Steel = Solid Rear Wheel = Standart ISO9001 = Standart ISO 13485 = American Standart ( FDA) , CE = Standart TUV = Roda belakang menggunakan bahan karet padat (ban mati) = Dimensi 94 x 23 x 89 cm = Menggunakan Ban Mati (tidak menggunakan angin) = Maximum Berat 100 Kg = Berat Kotor 19,6 Kg *) IV hand anak 1 Unit = Intravenous injection training model (with motor) infant / pediatric csiv I Kruk (Crutches dengan ujung berlapis karet) 2 Unit = Kerangka terbuat dari bahan aluminium Tinggi dan panjang lengan yang dapat disesuaikan Bantalan ketiak yang lunak, berputar seiring dengan gerakan tubuh Pegangan ergonomis membentuk kontur anatomi tubuh Pegangan ergonomis khusus untuk tangan kanan dan kiri Kaki diimbangi untuk memberikan jarak pinggul dan mengurangi potensi tersandung Ujung tongkat dilengkapi dengan karet, anti licin Beban maksimum hingga 136 kg Harga tongkat 1 pasang (kiri dan kanan) Alat perawatan tali pusat 1 Unit = PHANTOM MANIKIN BAYI PLASENTA SILIKON/ MANEKIN BAYI PLASENTA Stetoskop untuk tindakan mengukur tekanan darah 3 Unit = "Fitur : - Dua-sisi chestpiece dengan diafragma merdu untuk pengecekan pada orang dewasa dan anak. - Generasi tubing dengan teknologi terbaru memberikan kekuatan lebih lama karena peningkatan resistensi terhadap minyak kulit dan alkohol ; di design cenderung mudah untuk membersihkan noda di seluruh bagian stetoskop. - Sisi Pediatric mengkonversi ke bell/suara terbuka tradisional dengan mengganti satu bagian diafragma dengan rim non-chill. - Diafragma merdu kecil berguna untuk anak, kecil, atau pasien tipis; sekitar perban; dan untuk penilaian karotis. - Chestpiece stainless steel presisi-mesin menjadi estetis, - Eartips Snap-Tight memiliki permukaan halus lembut memberikan kenyamanan." Foot stool / foot board 4 Unit = "Dimensi per Produk P 40 cm x L 45 cm x T 40 cm (72.000 cm3)"', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 503566);
