INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63067646', 63067646, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'POLITEKNIK KESEHATAN MALANG', 'Belanja Modal Peralatan Dan Mesin – BLU Pengadaan ABBM Laboratorium Pendidikan Laboratorium Kebidanan Jember Berupa Opthalmoscope, Manikin injeksi IM, Kit konseling menyusui (boneka bayi, belly ball, breastmodel, gelas sloki, tas konseling kit), Phantom full body ibu/anak, Phantom bayi untuk pemberian imunisasi, EKG, Breast self examination models, Phantom uterus, Stetoskop bayi untuk penanganan asfiksia, neonatal suction machine, Sterilisator Oven, Phantom NGT, Phantom lengan untuk pasang infus, Sound System, dan White Board.', 'Barang', 'E-Purchasing', 'Jawa Timur, Malang (Kota)', 121993000, 'January 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '18 Unit', 'Opthalmoscope = 1 Unit Manikin injeksi IM = 1 Unit Kit konseling menyusui (boneka bayi, belly ball, breastmodel, gelas sloki, tas konseling kit) = 2 Unit Phantom full body ibu/anak = 1 Unit Phantom bayi untuk pemberian imunisasi = 1 Unit EKG = 1 Unit Breast self examination models = 1 Unit Phantom uterus = 1 Unit Stetoskop bayi untuk penanganan asfiksia = 2 Unit neonatal suction machine = 1 Unit Sterilisator Oven = 1 Unit Phantom NGT = 1 Unit Phantom lengan untuk pasang infus = 2 Unit Sound System = 1 Unit White Board = 1 Unit', 'Opthalmoscope 1 Unit = Ophthalmoscope LED ( A ) - "Mitch" Manikin injeksi IM 1 Unit = "Features: 1. Structure of left gluteal: osteal marks, gluteal muscules, ischiadic nerve and veins 2. Left gluteal can be taken off. So it is easy to observe internal structure and make sure position of ischiadic nerve and veins. 3. Gluteal intramuscular injection training Size:39cm*40cm*41cm G.W.:4kg" Kit konseling menyusui (boneka bayi, belly ball, breastmodel, gelas sloki, tas konseling kit) 2 Unit = manekin Bahan kain Paket Standar Konseling KIT Menyusui terdiri dari : 1. Boneka Bayi, panjang 40 cm, namun penampakan besar boneka ril besar bayi baru lahir, kepala bisa diputar untuk memperagakan posisi pelekkatan yg tepat. 2. Belly Ball, digunakan sebagai peraga analogi ukuran lambung bayi sesuai usia, terdiri dari kelereng kecil, kelereng besar, bola pimpong, dan telur ayam plastik 3. Breastmodel, boneka peraga payudara 4. Gelas sloki kaca 5. NGT FR 5 50 cm merk romson, digunakan untuk peraga proses relaktasi 6. spuit 20 cc utuh 7 spuit 20 cc ujung dipotong untuk Peraga menarik puting pada inverted niple 8. Tas konseling kit, terbuat dari bahan plastik mika buram ukuran besar, muat untuk semua perlengkapan konseling. rapih dan anti air. terdapat logo tulisan konseling kit menyusui Phantom full body ibu/anak 1 Unit = "PHANTOM MANEKIN MULTIFUNGSI FULL BODY TERBUAT DARI BAHAN SILICON DILENGKAPI FUNGSI: 1. CPR 2. NGT 3. WSD 4. COLOSTOMY 5. CATETER MALE & FEMALE 6. INJEKSI 7. BREAST CARE 8. HUKNA 9. LAMPU INDIKATOR CPR 10. PENUTUP DADA BISA DI BUKA" Phantom bayi untuk pemberian imunisasi 1 Unit = "PHANTOM MANEKIN BAYI INJEKSI TERBUAT DARI BAHAN SILICON" EKG 1 Unit = Alat ECG/EKG 12 Channel Breast self examination models 1 Unit = "PHANTOM MANEKIN PERAWATAN PAYUDARA / BREASTCARE TERBUAT DARI BAHAN SILICON" Phantom uterus 1 Unit = "Alat Model perkembangan janin Spesifikasi Produk: Terdapat 8 buah model perkembangan embryo manusia, bahan terbuat dari plastik PVC, setiap model memilik dudukan terbuat dari plastik ABS dengan ukuran 12 x 12 cm. Jenis Alat: alat peraga Uji Fungsi: alat peraga Keterangan Lainnya: Terdapat 8 buah model perkembangan embryo manusia, bahan terbuat dari plastik PVC, setiap model memilik dudukan terbuat dari plastik ABS dengan ukuran 12 x 12 cm." Stetoskop bayi untuk penanganan asfiksia 2 Unit = STETOSKOP LITTMANN BAYI neonatal suction machine 1 Unit = "- Batas tekanan negative: > 0.075 MPa (680 mmHg) - Dimensi unit: 280x195x285 mm - Adjustable vacuum range : 0.02 MPa - Limit negative pressure max airflow : > 15 LPM - Sound Level : 65dB (A) - Suction Bottle : 1000mL/PC - Input Power : 90Va" Sterilisator Oven 1 Unit = Portable Autoclave Phantom NGT 1 Unit = "PHANTOM MANEKIN NGT SONDE TERBUAT DARI BAHAN SILICON" Phantom lengan untuk pasang infus 2 Unit = "PHANTOM MANEKIN PEMASANGAN INFUS LENGAN PRODUK TERBUAT DARI BAHAN SILICON DILENGKAPI DENGAN TIANG PENYANGGA INFUS DAN 1 BOTOL AIR INFUS" Sound System 1 Unit = Single Woofer 15 inch Dual Power (AC & Battery) 3-Band Tone Control Buetooth Connection + Polytron Audio Connect USB, SD Card/MMC, Optical, Aux, Line Input, 1 Mic Input, 2 Wireless Mic FM Radio Power Output: 120 WRMS Spesifikasi TeknisPolytron Professional Speaker adalah bluetooth speaker dengan suara berkelas, hasilkan suara mid-treble lebih jernih dan bass lebih mantap, serta dilengkapi built-in battery, handle, dan roda. Makin lengkap dengan 1 Mic Input with Echo Control dan 2 Wireless Mic untuk karaoke bersama teman atau keluarga. Dual Power (AC & Battery) Battery Life up to 7 Hours Handle & Wheels 2-Way Speaker System Woofer 15 inch LED Display Bass, Middle, Treble Control Bluetooth Connection Supported with Polytron Audio Connect App USB, SD Card/MMC, Optical, Aux, Line Input FM Radio 2 Wireless Mic Included 1 Mic Input with Echo Control Mic Priority Remote Control Power Output: 120 WRMS White Board 1 Unit = "Papan Flipchart ukuran 60 X 90 Lebih Mudah Dihapus Bersih Kualitas Kokoh Dan Stabil Tidak Gampang Pecah Frame / Bingkai Tidak Mudah Copot, Tidak Tajam Kaki yang tingginya dapat disesuaikan Bentuknya selalu potrait / vertikal / berdiri Papan Magnetik"', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 505951);
